execution.command:
$src = @'
using System;
using System.Runtime.InteropServices;
public class BlockDlls
{
    [DllImport("kernel32.dll")]
    public static extern bool SetProcessMitigationPolicy(int policy, ref int buffer, IntPtr size);
    public static bool EnableMicrosoftSignedOnly()
    {
        // PROCESS_MITIGATION_SIGNATURE_POLICY：bit0 = MicrosoftSignedOnly
        int buf = 0x01;
        return SetProcessMitigationPolicy(7, ref buf, (IntPtr)4);
    }
}
'@
Add-Type -TypeDefinition $src
if ([BlockDlls]::EnableMicrosoftSignedOnly()) { Write-Output 'ProcessSignaturePolicy MicrosoftSignedOnly=ON' } else { Write-Output 'ProcessSignaturePolicy apply FAILED' }

